   567|        return try {
   568|            val resp = http.post("$base$path") {
   569|                authHeaders().forEach { (k, v) -> header(k, v) }
   570|                contentType(ContentType.Application.Json)
   571|                setBody(body)
   572|            }
   573|            if (resp.status.isSuccess()) {
   574|                Result.success(Unit)
   575|            } else {
   576|                Result.failure(Exception("Sync failed (${resp.status.value})"))
   577|            }
   578|        } catch (e: Exception) {
   579|            Result.failure(e)
   580|        }
   581|    }
